def binary_search(arr: list[int], target: int) -> int:
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def fib(n: int) -> int:
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

def process_data(n: int) -> int:
    ops = 0
    for i in range(n):
        j = n
        while j > 1:
            ops += 1
            j //= 2
    return ops

def scan_triangular(grid: list[list[int]]) -> int:
    n = len(grid)
    total = 0
    for i in range(n):
        for j in range(i, n):
            total += grid[i][j]
    return total

def prefix_scan(arr: list[int]) -> list[int]:
    n = len(arr)
    res = [0] * (n + 1)
    for i in range(n):
        res[i + 1] = res[i] + arr[i]
    return res
